#!/usr/bin/env python3
"""Ross's transcript tool: append untranscribed Friend-Message commits to episode files."""
import subprocess, re, sys, os, datetime

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
WORK = "/tmp/wt-main-edit"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def git(*args, cwd=REPO):
    return subprocess.run(["git"] + list(args), cwd=cwd, capture_output=True, text=True).stdout


def collect():
    msgs = []
    for b in BRANCHES:
        out = git("log", "--format=%H", f"origin/friend/{b}")
        for sha in out.split():
            body = git("show", sha, "-s", "--format=%B")
            if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
                continue
            ep = re.search(r"^Episode:\s*(.+?)\s*$", body, re.M)
            sp = re.search(r"^Speaker:\s*(.+?)\s*$", body, re.M)
            if not ep or not sp:
                continue
            ct = int(git("log", "-1", "--format=%ct", sha).strip())
            # utterance = everything after the blank line following Reply-To
            m = re.search(r"^Reply-To:.*?\n\n", body, re.M | re.S)
            text = body[m.end():] if m else body
            text = text.rstrip("\n")
            msgs.append({
                "ep": ep.group(1), "sha": sha, "ct": ct, "branch": b,
                "speaker": sp.group(1), "text": text,
            })
    return msgs


def done_shas():
    done = set()
    for f in sorted(os.listdir(WORK)):
        pass
    out = git("ls-tree", "-r", "origin/main", "--name-only", cwd=REPO)
    for path in out.split():
        if re.match(r"^S\d+/E\d+\.md$", path):
            done |= set(re.findall(r"[0-9a-f]{40}", git("show", f"origin/main:{path}")))
    return done


def ts(ct):
    return datetime.datetime.utcfromtimestamp(ct).strftime("%Y-%m-%dT%H:%M:%SZ")


def main():
    msgs = collect()
    done = done_shas()
    missing = [m for m in msgs if m["sha"] not in done]
    missing.sort(key=lambda m: (m["ct"], m["sha"]))
    by_ep = {}
    for m in missing:
        by_ep.setdefault(m["ep"], []).append(m)
    for ep, items in by_ep.items():
        path = os.path.join(WORK, ep + ".md")
        if not os.path.exists(path):
            print(f"SKIP (no file): {ep}")
            continue
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()
        if not content.endswith("\n"):
            content += "\n"
        blocks = []
        for m in items:
            blocks.append(
                f"**{m['speaker']}** ({ts(m['ct'])})\n\n"
                f"Source: friend/{m['branch']} @ {m['sha']}\n\n"
                f"{m['text']}\n"
            )
        content += "\n\n" + "\n\n".join(blocks)
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"{ep}: appended {len(items)} entries")
        for m in items:
            print(f"   {ts(m['ct'])} {m['speaker']:8} {m['sha'][:10]} {m['branch']}")
    if not by_ep:
        print("nothing to append")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Verify every transcript entry on main matches its source commit verbatim, and that
no Friend-Message commit is missing from any episode file."""
import subprocess, re, os, datetime

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def git(*args):
    return subprocess.run(["git"] + list(args), cwd=REPO, capture_output=True, text=True).stdout


def body_of(sha):
    b = git("show", sha, "-s", "--format=%B")
    m = re.search(r"^Reply-To:.*?\n\n", b, re.M | re.S)
    return (b[m.end():] if m else b).rstrip("\n")


def main():
    # 1. every entry in the transcript files
    files = git("ls-tree", "-r", "origin/main", "--name-only").split()
    ep_files = [f for f in files if re.match(r"^S\d+/E\d+\.md$", f)]
    entries = {}   # sha -> (file, speaker, ts, text)
    order = {}     # file -> [sha,...]
    problems = []
    for f in sorted(ep_files):
        content = git("show", f"origin/main:{f}")
        order[f] = []
        # frontmatter
        if not content.startswith("---\n"):
            problems.append(f"{f}: no frontmatter")
        fm = re.match(r"---\n(.*?)\n---\n", content, re.S)
        if fm:
            for key in ("title", "summary", "season", "episode", "status"):
                if not re.search(rf"^{key}:", fm.group(1), re.M):
                    problems.append(f"{f}: frontmatter missing {key}")
            summ = re.search(r'^summary: "(.*)"$', fm.group(1), re.M)
            after = content[fm.end():].lstrip("\n")
            para = after.split("\n\n")[0].strip()
            if summ and para != summ.group(1):
                problems.append(f"{f}: summary paragraph differs from frontmatter")
        else:
            problems.append(f"{f}: malformed frontmatter")
        # entries
        for m in re.finditer(
            r"\*\*(\w[\w ]*)\*\* \((\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)\)\n\n"
            r"Source: friend/(\w+) @ ([0-9a-f]{40})\n\n(.*?)(?=\n\n\*\*|\Z)",
            content, re.S):
            speaker, ts, br, sha, text = m.groups()
            if sha in entries:
                problems.append(f"DUPLICATE sha {sha} in {f} and {entries[sha][0]}")
            entries[sha] = (f, speaker, ts, br, text)
            order[f].append(sha)
        # stray Source lines not inside an entry
        n_src = len(re.findall(r"^Source: friend/", content, re.M))
        n_ent = len(re.findall(r"^Source: friend/(\w+) @ ([0-9a-f]{40})$", content, re.M))
        if n_src != n_ent:
            problems.append(f"{f}: {n_src} Source lines vs {n_ent} well-formed")

    # 2. every Friend-Message commit
    msgs = {}
    for b in BRANCHES:
        for sha in git("log", "--format=%H", f"origin/friend/{b}").split():
            body = git("show", sha, "-s", "--format=%B")
            if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
                continue
            ep = re.search(r"^Episode:\s*(.+?)\s*$", body, re.M).group(1)
            msgs[sha] = (ep, b, body_of(sha))

    for sha, (ep, br, text) in msgs.items():
        if sha not in entries:
            problems.append(f"MISSING {br} {sha[:10]} declared episode {ep}")
            continue
        f, speaker, ts, ebr, etext = entries[sha]
        if etext != text:
            problems.append(f"TEXT MISMATCH {sha[:10]} in {f}")
        if ebr != br:
            problems.append(f"BRANCH MISMATCH {sha[:10]} {ebr} != {br}")
        if f != ep + ".md":
            problems.append(f"EPISODE MISMATCH {sha[:10]} {f} != {ep}.md")
        sp = re.search(r"^Speaker:\s*(.+?)\s*$", git("show", sha, "-s", "--format=%B"), re.M).group(1)
        if speaker != sp:
            problems.append(f"SPEAKER MISMATCH {sha[:10]} {speaker} != {sp}")
        ct = int(git("log", "-1", "--format=%ct", sha).strip())
        want = datetime.datetime.fromtimestamp(ct, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        if ts != want:
            problems.append(f"TIMESTAMP MISMATCH {sha[:10]} {ts} != {want}")

    print(f"episode files: {len(ep_files)}, entries: {len(entries)}, source commits: {len(msgs)}")
    for f in sorted(ep_files):
        n = len(order[f])
        if n:
            print(f"  {f}: {n}")
    if problems:
        print("\nPROBLEMS:")
        for p in problems:
            print("  " + p)
    else:
        print("\nOK: transcript complete and verbatim, no duplicates.")


if __name__ == "__main__":
    main()
